/** Lightweight runtime translations keyed to the WordPress site language. */
final class WhisperLink_I18n {
    private static function language(): string {
        $locale = (string) get_option('WPLANG', '');
        if ($locale === '') $locale = function_exists('get_locale') ? (string) get_locale() : 'en_US';
        $code = strtolower(substr($locale, 0, 2));
        return in_array($code, ['ar', 'fr', 'en'], true) ? $code : 'en';
    }

    public static function lang(): string { return self::language(); }
    public static function dir(): string { return self::language() === 'ar' ? 'rtl' : 'ltr'; }

